#include <iostream>
#include <sstream>
#include <string>
#include <vector>

std::string reverseWords(const std::string& text) {
    std::istringstream stream(text);
    std::vector<std::string> words;
    std::string word;
    while (stream >> word) {
        words.push_back(word);
    }
    std::string result;
    for (auto it = words.rbegin(); it != words.rend(); ++it) {
        if (!result.empty()) {
            result += " ";
        }
        result += *it;
    }
    return result;
}

int main() {
    std::string text;
    std::getline(std::cin, text);
    std::cout << reverseWords(text) << "\n";
    return 0;
}

